-- Generated by scripts/build-ai-form-concept-catalog.ts.
-- Apply concept core, deploy matching ask-bob AND bob-worker, then publish.
begin;
do $form_publication$
declare prior shared.ai_prompt_versions; definition jsonb; key text; next_version integer; vid uuid; activation jsonb:='{}';
 workflow jsonb:=$form_workflow${"name":"workflow_solution_concept","card":"Explore and correct early 2D geometry on a Solution before detailed construction.","method":"For uncertain physical form, agree geometry cheaply before detailed construction: use a Solution design_intent.model and its deterministic plan/profile or named principle section. Read its current edit context, preserve feature and choice links, make bounded corrections, and reopen the saved version and reported gaps. Select the exact Solution through existing target decisions when the direction is settled. Concept dimensions remain decisions, estimates or unknowns; no Building or measured fact is created. Construction retains these identities and dimensions through existing Artifact lineage, K2 and independent CAD review. This first slice maps unrotated boxes exactly; unsupported shapes/subdivision remain explicit. A sketch is useful when it resolves uncertainty, not a compulsory phase or approval for every edit.","tools":["read_project_edit_context","edit_project_record","read_solution_context","create_solution_alternative","select_solution_alternative"]}$form_workflow$::jsonb;
 description text:=$form_description$Revise the record returned by read_project_edit_context using only the requested changes. Never creates an alternative. Existing fields, measurements, image links and nested decisions are preserved. Editing a selected solution also advances that same selection atomically. Changes use content paths and JSON-encoded values. Text fields: /description, /title, /assumptions, /tradeoffs. Design fields: /design_intent/summary or /purpose; features and choices use zero-based indices from the read. Append a feature or choice at /design_intent/features/- or /choices/- without id (feature source_ref is server-owned). Replace individual content fields; remove a feature/choice explicitly. Identity and source-link edits are unavailable here. A null design_intent can be initialized by setting its summary (purpose defaults to concept). Changes reset alignment to draft unless /design_intent/alignment is explicitly set with an honest status and basis. A failed edit must never be replaced with a create. Early 2D design uses optional /design_intent/model on this same Solution, before target selection. Initialize once with {version:1,frame:{origin,x,y,z} (plain axis descriptions),nodes,components,views,constraints,unsupported:[]}. Nodes reuse CAD parameters: {id,role:decision|estimate,value,unit:mm|scalar,reason}, {id,role:unknown,unit,reason}, or {id,role:derived,operation:add_v1|subtract_v1|multiply_v1|divide_v1,operands:[id,id],rounding:exact|half_away_6}. No measured/source nodes. Components: {id,label,kind:solid|space|opening,active:true,position:[node,node,node],size:[node,node,node],features:[feature_id],choices:[choice_id]}. Views: {id,label,plane:XY|XZ|YZ,kind:projection|section,at:null|node}; include an XY projection and a profile; section at names the perpendicular coordinate. Constraints: {id,label,relation:equal|at_most,left:node,right:node,feature:null|feature_id}. View requirements use constraints {id,label,relation:view_plane,view:view_id,plane:XY|XZ|YZ,feature:null|feature_id}. Use returned concept_links. IDs are local letters/digits/underscore/hyphen, start with a letter, max 32. Subsequent changes set /design_intent/model/<nodes|components|views|constraints>/<index>/<field>, append at /-, or set frame/unsupported. Node content may be replaced at its index with the SAME id. Components deactivate via active=false; do not replace lists or identities. Unknowns/conflicts stay saved and visible. Every view derives from this model; openings are annotated volumes, not boolean cuts. Unsupported forms belong in unsupported. Saving is not construction or safety approval.$form_description$;
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if to_regprocedure('bob_private.solution_concept_result(jsonb)') is null then raise exception 'concept_core_required'; end if;
 foreach key in array array['tools.edit_project_record','bob.workflows'] loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=key for update of p;
  if not found then raise exception 'concept_catalog_dependency_missing'; end if;
  definition:=prior.definition;
  if key='tools.edit_project_record' then
   definition:=jsonb_set(definition,'{description}',to_jsonb(description));
  else
   if exists(select 1 from jsonb_array_elements(definition->'workflows') w where w->>'name'=workflow->>'name') then raise exception 'concept_method_already_exists'; end if;
   definition:=jsonb_set(definition,'{workflows}',definition->'workflows'||jsonb_build_array(workflow));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','form-concept-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into vid;
  activation:=activation||jsonb_build_object(key,vid);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $form_publication$;
commit;
